[DataMember,
AifQueryTypeAttribute('_packedQuery', queryStr(MET_PurchTableQuery))]
public str parmQuery(str _packedQuery = queryPack)
{
    queryPack = _packedQuery;
    return queryPack;   
}

[DataMember]
public int parmBatchSize(int _batchSize = batchSize)
{
    batchSize = _batchSize;
    return batchSize;
}

public str setQuery(Query _query)
{
    querypack = SysOperationHelper::base64Encode(_query.pack());
    return querypack;
